head.script:
///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.libRoundPanel.PanelToGroupBox(panel_Top_1);
        $c.cm.PanelToGroupBox(panel_Top_2);
        rdo_gubun1.setValue("1");
        rdo_gubun2.setValue("1");
        await scwin.init();
        // fn_list_sync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08061.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init = async function() {
    const dateTmp = $c.ut.cGetToday("yyyymmdd");
    cmb_month1.setValue(dateTmp.substring(4, 6));
    cmb_month2.setValue(dateTmp.substring(4, 6));
    cmb_month3.setValue(dateTmp.substring(4, 6));
    cmb_month4.setValue(dateTmp.substring(4, 6));
    cmb_month5.setValue(dateTmp.substring(4, 6));
    cmb_month6.setValue(dateTmp.substring(4, 6));

    // 기준년 (콤보박스)
    const sbmOptions = {
        id : "sbm_dts_year1",
        action : "/ElwNcr.do",
        ref : "",
        target : "dts_year1=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const sbmOptions2 = {
        id : "sbm_dts_year2",
        action : "/ElwNcr.do",
        ref : "",
        target : "dts_year2=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const sbmOptions3 = {
        id : "sbm_dts_year3",
        action : "/ElwNcr.do",
        ref : "",
        target : "dts_year3=body.content",
        isProcessMsg : false
    };

    const sbmRtn3 = await $c.sbm.executeDynamic(sbmOptions3);
    // TODO Stage2: sbmRtn3 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const sbmOptions4 = {
        id : "sbm_dts_year4",
        action : "/ElwNcr.do",
        ref : "",
        target : "dts_year4=body.content",
        isProcessMsg : false
    };

    const sbmRtn4 = await $c.sbm.executeDynamic(sbmOptions4);
    // TODO Stage2: sbmRtn4 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const sbmOptions5 = {
        id : "sbm_dts_year5",
        action : "/ElwNcr.do",
        ref : "",
        target : "dts_year5=body.content",
        isProcessMsg : false
    };

    const sbmRtn5 = await $c.sbm.executeDynamic(sbmOptions5);
    // TODO Stage2: sbmRtn5 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const sbmOptions6 = {
        id : "sbm_dts_year6",
        action : "/ElwNcr.do",
        ref : "",
        target : "dts_year6=body.content",
        isProcessMsg : false
    };

    const sbmRtn6 = await $c.sbm.executeDynamic(sbmOptions6);
    // TODO Stage2: sbmRtn6 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const sbmOptions7 = {
        id : "sbm_dts_inst",
        action : "/etn/EtnCodeAct.do",
        ref : "",
        target : "dts_inst=body.content",
        isProcessMsg : false
    };

    const sbmRtn7 = await $c.sbm.executeDynamic(sbmOptions7);
    // TODO Stage2: sbmRtn7 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const sbmOptions8 = {
        id : "sbm_dts_lp",
        action : "/etn/EtnCodeAct.do",
        ref : "",
        target : "dts_lp=body.content",
        isProcessMsg : false
    };

    const sbmRtn8 = await $c.sbm.executeDynamic(sbmOptions8);
    // TODO Stage2: sbmRtn8 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const sbmOptions9 = {
        id : "sbm_dts_srty",
        action : "/etn/EtnCodeAct.do",
        ref : "",
        target : "dts_srty=body.content",
        isProcessMsg : false
    };

    const sbmRtn9 = await $c.sbm.executeDynamic(sbmOptions9);
    // TODO Stage2: sbmRtn9 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    cmb_inst_lp.ComboDataID = "dts_inst";
    scwin.changeGubun1("1");
    scwin.changeGubun2("1");
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name rdo_gubun1_onselchange
 * @description rdo_gubun1 onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.rdo_gubun1_onselchange = function() {
    try {
        scwin.changeGubun1(rdo_gubun1.getValue());
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF08061.rdo_gubun1_onselchange" });
    }
};

/**
 * @method
 * @name rdo_gubun2_onselchange
 * @description rdo_gubun2 onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.rdo_gubun2_onselchange = function() {
    try {
        scwin.changeGubun2(rdo_gubun2.getValue());
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF08061.rdo_gubun2_onselchange" });
    }
};

/**
 * @method
 * @name cmb_instlp_select2_onselchange
 * @description cmb_instlp_select2 onselchange 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.cmb_instlp_select2_onselchange = async function() {
    try {
        if (cmb_instlp_select2.BindColVal === "01") {
            cmb_inst_lp.ComboDataID = "dts_inst";
        } else if (cmb_instlp_select2.BindColVal === "02") {
            cmb_inst_lp.ComboDataID = "dts_lp";
        } else {
            await $c.win.alert(cmb_instlp_select2.BindColVal);
        }
        cmb_inst_lp.setSelectedIndex(0);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08061.cmb_instlp_select2_onselchange" });
    }
};

